 */
void kdf(
    uint8_t *first_dst, size_t first_len,
    uint8_t *second_dst, size_t second_len,
    uint8_t *third_dst, size_t third_len,
    const uint8_t *data, size_t data_len,
    const uint8_t chaining_key[NOISE_HASH_LEN]);

#ifdef __cplusplus
}
#endif

#endif // HKDF_H

